/// Tab in the input moves to the next tab, + then Spec then back to Code,
/// and Shift+Tab back the other way, without indenting the text or taking
/// focus out of the input.
#[gpui_kit::test]
async fn tab_cycles_the_tabs_and_keeps_focus(cx: &mut TestAppContext) {
    cx.update(|cx| {
        gpui_kit::init(cx);
        piton_syntax::init();
        ProjectDirectory::init(cx);
    });
    let mut chat_input = None;
    let window = cx.add_window(|window, cx| {
        let input = cx.new(|cx| ChatInput::new(window, cx));
        chat_input = Some(input.clone());
        Root::new(input, window, cx)
    });
    let chat_input = chat_input.unwrap();
    let handle = window.into();
    cx.wait_for(handle, TIMEOUT, |window, _| {
        window.try_find("prompt-editor").is_some()
    })
    .await;

    cx.update_window(handle, |_, window, cx| window.input("hi", cx))
        .unwrap();
    cx.run_until_parked();
    let presses = [
        ("tab", 1),
        ("tab", 2),
        ("tab", 0),
        ("tab", 1),
        ("shift-tab", 0),
        ("shift-tab", 2),
        ("shift-tab", 1),
    ];
    for (key, expected) in presses {
        cx.update_window(handle, |_, window, cx| window.press(key, cx))
            .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            let input = chat_input.read(cx);
            assert_eq!(input.selected_tab, expected, "after {key}");
            assert_eq!(input.value(cx).as_ref(), "hi");
            assert!(input.is_focused(window, cx), "the input lost focus on {key}");
        })
        .unwrap();
    }
}

/// The + tab floats between Code and Spec: a square a little shorter than
/// the tabs either side of it, clear of both and centred on them.
#[gpui_kit::test]
async fn plus_tab_floats_between_the_tabs(cx: &mut TestAppContext) {
    cx.update(|cx| {
        gpui_kit::init(cx);
        piton_syntax::init();
        ProjectDirectory::init(cx);
    });
    let window = cx.add_window(|window, cx| {
        let input = cx.new(|cx| ChatInput::new(window, cx));
        Root::new(input, window, cx)
    });
    let handle = window.into();
    cx.wait_for(handle, TIMEOUT, |window, _| {
        window.try_find("prompt-editor").is_some()
    })
    .await;

    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        let code = window.within("code-tab").find(0usize).bounds();
        let spec = window.within("spec-tab").find(0usize).bounds();
        let plus = window.find("both-tab").bounds();
        assert_eq!(
            plus.size.width, plus.size.height,
            "+ tab {plus:?} is not square"
        );
        assert!(
            plus.size.height < code.size.height,
            "+ tab {plus:?} is not shorter than Code {code:?}"
        );
        assert!(
            code.right() < plus.left() && plus.right() < spec.left(),
            "+ tab {plus:?} is not clear between Code {code:?} and Spec {spec:?}"
        );
        assert!(
            (plus.center().y - code.center().y).abs() <= super::px(0.5),
            "+ tab {plus:?} is not centred on Code {code:?}"
        );
    })
    .unwrap();
}

/// With one line of text, the input is as tall as the Send button and
/// lines up with it.
#[gpui_kit::test]
async fn single_line_input_lines_up_with_send_button(cx: &mut TestAppContext) {
    cx.update(|cx| {
        gpui_kit::init(cx);
        piton_syntax::init();
        ProjectDirectory::init(cx);
    });
    let window = cx.add_window(|window, cx| {
        let input = cx.new(|cx| ChatInput::new(window, cx));
        Root::new(input, window, cx)
    });
    let handle = window.into();
    cx.wait_for(handle, TIMEOUT, |window, _| {
        window.try_find("prompt-editor").is_some()
    })
    .await;

    cx.update_window(handle, |_, window, cx| {
        // A second frame sizes the input from the editor's laid-out line height.
        window.render_frame(cx);
        let editor = window.find("prompt-editor").bounds();
        let send = window.find("send").bounds();
        assert!(
            (editor.size.height - send.size.height).abs() <= gpui_kit::px(1.),
            "input {editor:?} and Send {send:?} differ in height"

